import{_ as a,o as t,c as n,l as o,t as r,N as s}from"./chunks/framework.Gjrf2Eoj.js";const _=JSON.parse('{"title":"ip-ntable | x-cmd man (ip man8) | neighbour table configuration","titleTemplate":false,"description":"x-cmd man (ip man8 Manual Page) | ip-ntable - neighbour table configuration","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"ip-ntable | x-cmd man (ip man8) | neighbour table configuration"}],["meta",{"name":"og:description","content":"x-cmd man (ip man8 Manual Page) | ip-ntable - neighbour table configuration"}]]},"headers":[],"params":{"isMan":true,"man":"ip-ntable","category":"ip man8","desc":"neighbour table configuration"},"relativePath":"ip/man8/ip-ntable.md","filePath":"ip/man8/ip-ntable.md"}'),i={name:"ip/man8/ip-ntable.md"},l={class:"visually-hidden"},m=s('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>ip-ntable - neighbour table configuration</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>ip</strong> [ <em>OPTIONS</em> ] <strong>ntable</strong> { <em>COMMAND</em> | <strong>help</strong> }</p><p><strong>ip ntable change name</strong> <em>NAME</em> [ <strong>dev</strong> <em>DEV</em> ] [ <strong>thresh1</strong><em>VAL</em> ] [ <strong>thresh2</strong> <em>VAL</em> ] [ <strong>thresh3</strong> <em>VAL</em> ] [ <strong>gc_int</strong><em>MSEC</em> ] [ <strong>base_reachable</strong> <em>MSEC</em> ] [ <strong>retrans</strong> <em>MSEC</em> ] [ <strong>gc_stale</strong> <em>MSEC</em> ] [ <strong>delay_probe</strong> <em>MSEC</em> ] [ <strong>queue</strong> <em>LEN</em> ] [ <strong>app_probs</strong> <em>VAL</em> ] [ <strong>ucast_probes</strong> <em>VAL</em> ] [ <strong>mcast_probes</strong> <em>VAL</em> ] [ <strong>anycast_delay</strong> <em>MSEC</em> ] [ <strong>proxy_delay</strong> <em>MSEC</em> ] [ <strong>proxy_queue</strong> <em>LEN</em> ] [ <strong>locktime</strong><em>MSEC</em> ]</p><p><strong>ip ntable show</strong> [ <strong>dev</strong> <em>DEV</em> ] [ <strong>name</strong> <em>NAME</em> ]</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p><em>ip ntable</em> controls the parameters for the neighbour tables.</p><h3 id="ip-ntable-show-list-the-ip-neighbour-tables" tabindex="-1">ip ntable show - list the ip neighbour tables <a class="header-anchor" href="#ip-ntable-show-list-the-ip-neighbour-tables" aria-label="Permalink to &quot;ip ntable show - list the ip neighbour tables&quot;">​</a></h3><p>This commands displays neighbour table parameters and statistics.</p><dl><dt><strong>dev</strong> * DEV*</dt><dd>only list the table attached to this device.</dd><dt><strong>name</strong> * NAME*</dt><dd>only lists the table with the given name.</dd></dl><h3 id="ip-ntable-change-modify-table-parameter" tabindex="-1">ip ntable change - modify table parameter <a class="header-anchor" href="#ip-ntable-change-modify-table-parameter" aria-label="Permalink to &quot;ip ntable change - modify table parameter&quot;">​</a></h3><p>This command allows modifying table parameters such as timers and queue lengths.</p><dl><dt><strong>name</strong> * NAME*</dt><dd>the name of the table to modify.</dd><dt><strong>dev</strong> * DEV*</dt><dd>the name of the device to modify the table values.</dd></dl><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><p>ip ntable show dev eth0</p><blockquote><p>Shows the neighbour table (IPv4 ARP and IPv6 ndisc) parameters on device eth0.</p></blockquote><p>ip ntable change name arp_cache queue 8 dev eth0</p><blockquote><p>Changes the number of packets queued while address is being resolved from the default value (3) to 8 packets.</p></blockquote><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><br> <strong>ip</strong>(8)</p><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Manpage by Stephen Hemminger</p>',23);function h(e,d,p,g,b,c){return t(),n("div",null,[o("h1",l,r(e.$params.man),1),m])}const f=a(i,[["render",h]]);export{_ as __pageData,f as default};
